var t=[{title:`Waarom de weegschaal beweegt`,text:`Eten en drinken, hydratatie, natrium, opgeslagen glycogeen en andere normale processen laten je lichaamsgewicht van dag tot dag schommelen. Eén hoge of lage meting zegt niets betrouwbaars over spier of vet. Training kan je lichaamssamenstelling veranderen, ook als je totale gewicht nauwelijks beweegt.`},{title:`Meet elke keer op dezelfde manier`,text:`Weeg je jezelf, gebruik dan dezelfde weegschaal en een vergelijkbare routine in plaats van willekeurige tijden. Een weekgemiddelde is vaak nuttiger dan één meting. Taille- en andere meetlintmetingen zijn alleen vergelijkbaar als je dezelfde lichaamspunten en dezelfde spanning van het lint gebruikt.`},{title:`Foto’s zijn optioneel`,text:`Voortgangsfoto’s kunnen veranderingen in houding of uiterlijk laten zien, maar licht, camerahoek en kleding beïnvloeden ze sterk. Je hebt ze niet nodig als je focus op fitheid of kracht ligt, en ze helpen misschien niet als je zorgen hebt over je lichaamsbeeld of eten.`},{title:`Fitheid en gewicht zijn gescheiden`,text:`Beter bewegen, langer volhouden en sterker worden zijn echte resultaten, wat je postuur ook is. Maak je je zorgen over een onverwachte gewichtsverandering of een medische aandoening, praat dan met een zorgverlener.`},{title:`TrainUp gebruiken`,text:`Het Dashboard heeft een lichaamsgewichtlogboek, en of je het gebruikt is aan jou. Lees het als een trend over meerdere weken. TrainUp beschouwt lichaamsgewicht niet als maat voor fitheid en stelt geen afvaldoelen.`}];var a=[{label:`CDC: gezond gewicht en beweging`,url:`https://www.cdc.gov/healthy-weight-growth/losing-weight/`},{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var i={sections:t,sources:a};export{i as default,t as sections,a as sources};